/**
 * KS-1374 - local stacks may run the global limiter looser than the demo
 * (RATE_LIMIT_MAX_REQUESTS raised for scanning), so this file pins the limiter
 * at the DEMO figure: 2000 requests per 60 s window per address.
 * Wiring cells read index.ts (the KS-733 shape: no gateway test boots it).
 * Behaviour cells drive express-rate-limit with the same options at the demo
 * figure and the REAL skip predicate over a local socket: request 2001 is
 * refused with 429, and the read-only paths still skip.
 */
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import type { Server } from 'node:http';
import type { AddressInfo } from 'node:net';
import express from 'express';
import rateLimit from 'express-rate-limit';
import { shouldSkipGlobalRateLimit } from '../middleware/rateLimitSkip';

const DEMO_MAX = 2000;
const GATEWAY_SRC = readFileSync(join(__dirname, '..', 'index.ts'), 'utf8');
const COMPOSE = readFileSync(join(__dirname, '..', '..', '..', '..', 'docker-compose.yml'), 'utf8');

/** The global limiter call in index.ts, from app.use(rateLimit({ to its closing line. */
function globalLimiterCall(): string {
  const at = GATEWAY_SRC.indexOf('app.use(rateLimit({');
  if (at === -1) return '';
  return GATEWAY_SRC.slice(at, GATEWAY_SRC.indexOf('}));', at) + 4);
}

let server: Server;
let base = '';

beforeAll(async () => {
  const app = express();
  app.use(rateLimit({
    windowMs: 60 * 1000,
    max: DEMO_MAX,
    message: { success: false, error: { code: 'RATE_LIMIT_EXCEEDED', message: 'Too many requests, please try again later.' } },
    standardHeaders: true,
    legacyHeaders: false,
    skip: (req) => shouldSkipGlobalRateLimit({
      authHeader: (req.headers.authorization as string) || '',
      path: req.path,
      nodeEnv: 'demo',
      disableEnv: undefined,
    }),
  }));
  app.use((_req, res) => { res.json({ ok: true }); });
  await new Promise<void>((resolve) => { server = app.listen(0, '127.0.0.1', () => resolve()); });
  base = 'http://127.0.0.1:' + (server.address() as AddressInfo).port;
});

afterAll(async () => {
  server.closeAllConnections();
  await new Promise<void>((resolve) => { server.close(() => resolve()); });
});

describe('KS-1374 global limiter wiring in index.ts', () => {
  // RE-LABELLED, KS-1374 round 2, gate44 N-1347-6. This read `RED KS-1374 W1`, and it is GREEN at
  // develop: index.ts already reads the variable, so there never was a red half here. The label invited
  // a reader of the evidence to assume one. It is a CONTROL — the arms in the PR body are what prove it
  // can red.
  it('control KS-1374 W1: the global limiter max reads RATE_LIMIT_MAX_REQUESTS', () => {
    expect(globalLimiterCall()).toContain('max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS ||');
  });

  it('control KS-1374 W2: the global limiter keeps a 60 s window, standard headers, the shared skip and its 429 code', () => {
    const call = globalLimiterCall();
    expect(call).toContain('windowMs: 60 * 1000,');
    expect(call).toContain('standardHeaders: true,');
    expect(call).toContain('skip: (req) => shouldSkipGlobalRateLimit({');
    expect(call).toContain('RATE_LIMIT_EXCEEDED');
  });

  it('control KS-1374 D1: the compose fallback stays at the demo figure, so a local raise lives in .env only', () => {
    expect(COMPOSE).toContain('RATE_LIMIT_MAX_REQUESTS=${RATE_LIMIT_MAX_REQUESTS:-' + DEMO_MAX + '}');
  });
});

describe('KS-1374 global limiter behaviour at the demo figure', () => {
  it('control KS-1374 B1: the first 2000 requests in a window pass, under a 2000 per 60 s policy', async () => {
    const statuses: number[] = [];
    let policy = '';
    for (let i = 0; i < DEMO_MAX; i += 100) {
      const batch = await Promise.all(Array.from({ length: 100 }, () => fetch(base + '/api/v1/documents')));
      for (const r of batch) { statuses.push(r.status); await r.text(); }
      policy = batch[0].headers.get('ratelimit-policy') || '';
    }
    expect(statuses.filter((s) => s === 200).length).toBe(DEMO_MAX);
    expect(policy).toBe(DEMO_MAX + ';w=60');
  }, 60000);

  it('control KS-1374 B2: request 2001 in the same window is refused with 429 RATE_LIMIT_EXCEEDED', async () => {
    const r = await fetch(base + '/api/v1/documents');
    const body = await r.json();
    expect(r.status).toBe(429);
    expect(body.error.code).toBe('RATE_LIMIT_EXCEEDED');
  });

  it('control KS-1374 B3: with the budget spent, the read-only paths still skip the limiter', async () => {
    for (const path of ['/health', '/api/verification/abc']) {
      const r = await fetch(base + path);
      await r.text();
      expect(r.status).toBe(200);
    }
  });

  it('control KS-1374 B4: with the budget spent, a test_token bearer is still refused in demo, even with test tokens enabled', async () => {
    const before = process.env.ENABLE_TEST_TOKENS;
    process.env.ENABLE_TEST_TOKENS = 'true';
    try {
      const r = await fetch(base + '/api/v1/documents', { headers: { authorization: 'Bearer test_token_ks1374' } });
      await r.text();
      expect(r.status).toBe(429);
    } finally {
      if (before === undefined) delete process.env.ENABLE_TEST_TOKENS;
      else process.env.ENABLE_TEST_TOKENS = before;
    }
  });
});

/**
 * =============================================================================
 * KS-695 ask 3 (i) - THE GATEWAY DOOR for POST/GET /api/platform/organizations/erase-connector
 * =============================================================================
 * Platform S calls this route with the organisation's operational `sk_` key. It is the most
 * destructive thing a connector key can ask for, so it is gated exactly as the GDPR erasure
 * routes are (KS-843): `authenticateToken` then `attachScopes` then `requireScopeOrRole('subjects:erase',
 * ['connector'], SUBJECTS_ERASE_SCOPE_ENFORCED)`, with the grace path a connector key issued before
 * the scope existed needs.
 *
 * THE ORACLE IS THE UPSTREAM, not the status code (the KS-843 F-7 lesson): a stub originate records
 * every request it receives, and a refusal means it recorded NOTHING. These cells drive the REAL
 * router (`createProxyRoutes`), not a model of it.
 * =============================================================================
 */

import { describe, it, expect, beforeAll, afterAll, beforeEach, afterEach, vi } from 'vitest';
import express from 'express';
import http from 'node:http';
import type { AddressInfo } from 'node:net';
import type { RequestHandler } from 'express';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { createProxyRoutes } from '../routes/proxy';
import { logger } from '../utils/logger';

const FLAG = 'SUBJECTS_ERASE_SCOPE_ENFORCED';
const POST_PATH = '/api/platform/organizations/erase-connector';
const GET_PATH = POST_PATH + '/5f3c1a90-2b44-4d31-9e5a-0c8f2d61b7aa';
const BODY = '{"externalRef":"5f3c1a90-2b44-4d31-9e5a-0c8f2d61b7aa","keyId":"key-own"}';

let upstream: http.Server;
let upstreamPort = 0;
let received: Array<{ line: string; body: string }> = [];

beforeAll(async () => {
  upstream = http.createServer((req, res) => {
    let body = '';
    req.on('data', (c) => { body += c; });
    req.on('end', () => {
      received.push({ line: `${req.method} ${req.url}`, body });
      res.writeHead(200, { 'content-type': 'application/json' });
      res.end('{"ok":true}');
    });
  });
  await new Promise<void>((r) => upstream.listen(0, '127.0.0.1', () => r()));
  upstreamPort = (upstream.address() as AddressInfo).port;
});
afterAll(async () => {
  await new Promise<void>((r) => upstream.close(() => r()));
});
beforeEach(() => {
  received = [];
  delete process.env[FLAG];
});

const ROLE_ONLY = {
  userId: 'connector:platform-s:org-1', role: 'connector', authMethod: 'api_key',
  scopes: ['documents:read'], connectorId: 'platform-s:org-1', organizationId: 'org-1', tenantId: 'tenant-1',
};
const WITH_SCOPE = { ...ROLE_ONLY, scopes: ['documents:read', 'subjects:erase'] };
/** A non-connector principal with neither the scope nor an accepted role. */
const NOT_A_CONNECTOR = { userId: 'user-1', role: 'ORG_ADMIN', authMethod: 'email', scopes: [], organizationId: 'org-1', tenantId: 'tenant-1' };

function buildApp(user: object) {
  const authenticateToken = ((_required?: boolean) =>
    ((req, _res, next) => {
      (req as unknown as { user: object }).user = { ...user };
      next();
    }) as RequestHandler) as (required?: boolean) => RequestHandler;
  const app = express();
  // The real index.ts does not body-parse proxied prefixes (proxyPaths); the router sees the raw stream.
  app.use(
    createProxyRoutes({
      services: { originate: { url: `http://127.0.0.1:${upstreamPort}`, name: 'originate' } },
      authenticateToken,
      log: () => {},
    } as unknown as Parameters<typeof createProxyRoutes>[0]),
  );
  return app;
}

async function drive(user: object, method: 'POST' | 'GET', path: string): Promise<number> {
  const server = buildApp(user).listen(0, '127.0.0.1');
  await new Promise<void>((r) => server.once('listening', () => r()));
  const port = (server.address() as AddressInfo).port;
  const status = await new Promise<number>((resolve) => {
    const req = http.request(
      { host: '127.0.0.1', port, path, method, headers: { 'content-type': 'application/json' } },
      (res) => { res.resume(); resolve(res.statusCode ?? 0); },
    );
    req.on('error', () => resolve(-1));
    req.end(method === 'POST' ? BODY : undefined);
  });
  await new Promise<void>((r) => server.close(() => r()));
  return status;
}

describe('KS-695 ask 3 (i) - the erase-connector door', () => {
  let warn: ReturnType<typeof vi.spyOn>;
  beforeEach(() => {
    warn = vi.spyOn(logger, 'warn').mockImplementation((() => logger) as never);
  });
  afterEach(() => {
    warn.mockRestore();
  });

  it('CONTROL - a holder of the scope reaches originate on BOTH verbs, at the same path, and the POST body arrives intact', async () => {
    expect(await drive(WITH_SCOPE, 'POST', POST_PATH)).toBe(200);
    expect(await drive(WITH_SCOPE, 'GET', GET_PATH)).toBe(200);
    expect(received.map((r) => r.line)).toEqual([`POST ${POST_PATH}`, `GET ${GET_PATH}`]);
    expect(received[0].body).toBe(BODY);
  });

  it('🔴 ENFORCING - a role-only connector is refused 403 on both verbs and originate sees nothing', async () => {
    process.env[FLAG] = 'true';
    expect(await drive(ROLE_ONLY, 'POST', POST_PATH)).toBe(403);
    expect(await drive(ROLE_ONLY, 'GET', GET_PATH)).toBe(403);
    expect(received).toEqual([]);
  });

  it('🔴 GRACE (switch unset) - a role-only connector is admitted and logged, so Platform S\'s existing key keeps working', async () => {
    expect(await drive(ROLE_ONLY, 'POST', POST_PATH)).toBe(200);
    expect(received).toHaveLength(1);
    const graceLogs = warn.mock.calls.filter((c) => String(c[0]).includes('KS-843'));
    expect(graceLogs).toHaveLength(1);
    expect(graceLogs[0][1]).toMatchObject({ requiredScope: 'subjects:erase', method: 'POST', route: POST_PATH, enforceFlag: FLAG });
  });

  it('🔴 a principal with neither the scope nor the connector role is refused 403 in BOTH modes', async () => {
    for (const mode of [undefined, 'true']) {
      if (mode === undefined) delete process.env[FLAG]; else process.env[FLAG] = mode;
      expect(await drive(NOT_A_CONNECTOR, 'POST', POST_PATH), `flag=${String(mode)}`).toBe(403);
    }
    expect(received).toEqual([]);
  });

  it('🔴 ENFORCING - no spelling of the path walks around the gate (separators, case, trailing slash, query)', async () => {
    process.env[FLAG] = 'true';
    const shapes: Array<['POST' | 'GET', string]> = [
      ['POST', '/api/platform//organizations/erase-connector'],
      ['POST', '/api/platform/organizations//erase-connector'],
      ['POST', '//api/platform/organizations/erase-connector'],
      ['POST', '/API/PLATFORM/ORGANIZATIONS/ERASE-CONNECTOR'],
      ['POST', '/api/platform/organizations/Erase-Connector/'],
      ['POST', POST_PATH + '?x=1'],
      ['GET', '/api/platform/organizations/erase-connector//5f3c1a90-2b44-4d31-9e5a-0c8f2d61b7aa'],
      ['GET', '/API/PLATFORM/ORGANIZATIONS/ERASE-CONNECTOR/5f3c1a90-2b44-4d31-9e5a-0c8f2d61b7aa'],
    ];
    const reached: string[] = [];
    for (const [method, path] of shapes) {
      received = [];
      const status = await drive(ROLE_ONLY, method, path);
      if (received.length > 0) reached.push(`${method} ${path} -> ${status}, upstream saw ${received.map((r) => r.line).join(',')}`);
    }
    expect(reached, 'a spelling that reaches originate has walked around the gate').toEqual([]);
  });

  it('the prefix is on the gateway\'s no-body-parse list, or the proxied POST body would be consumed before the proxy', () => {
    const src = readFileSync(join(__dirname, '..', 'index.ts'), 'utf8');
    const block = /const proxyPaths = \[([\s\S]*?)\];/.exec(src)?.[1] ?? '';
    const entries = [...block.matchAll(/'([^']+)'/g)].map((m) => m[1]);
    // control: the list was actually parsed, and a long-standing member is in it
    expect(entries.length).toBeGreaterThan(10);
    expect(entries).toContain('/api/gdpr');
    expect(entries).toContain(POST_PATH);
  });
});

/**
 * =============================================================================
 * KS-1464 — limiter key hygiene (two minor findings from the Opus gate on #1463)
 * =============================================================================
 * Both are in middleware/rateLimitEnforce.ts. Every cell drives the REAL limiter with ONE fake Redis
 * injected through the module it shares with auth, so the assertions read the exact Redis KEYS counted.
 *
 *   B  the `jwt:<tenant>:<id>` bucket joined two claims with a bare ':'. Either claim may contain ':', so
 *      tenant `a:b` + id `x` and tenant `a` + id `b:x` both gave `jwt:a:b:x` and shared one bucket. Each part
 *      is now escaped ('%' first, then ':'), which is injective, leaves every ordinary id byte-identical,
 *      and, unlike encodeURIComponent, cannot throw on a lone surrogate (jwtBucket runs outside the try).
 *   T  the "no rateLimit" warning was throttled on `connectorId || userId` alone, so two tenants' principals
 *      sharing a connectorId shared one 30-second slot and one tenant's warning hid the other's. It is now
 *      throttled on the bucket the limiter counts under (which carries the tenant), and the line names the tenant.
 * Not here: the rolling-deploy note (old and new pods count machine-JWT principals under different keys for
 * one window), which is for the deploy seat; there is no production producer of a machine JWT.
 * =============================================================================
 */
import { describe, it, expect, beforeAll, afterAll, vi } from 'vitest';

const fakeRedis = vi.hoisted(() => ({ keys: [] as string[], counts: new Map<string, number>() }));
vi.mock('../services/redis', async (importOriginal) => {
  const real = (await importOriginal()) as Record<string, unknown>;
  const client = {
    status: 'ready',
    incr: async (k: string) => { fakeRedis.keys.push(k); const n = (fakeRedis.counts.get(k) ?? 0) + 1; fakeRedis.counts.set(k, n); return n; },
    pexpire: async () => 1,
    pttl: async () => 60000,
  };
  return { ...real, getRedisClient: () => client };
});

import { enforceClientRateLimit, recordApiKeyBucket } from '../middleware/rateLimitEnforce';

const EXPECTED_CELLS = 11;
let CELLS_RUN = 0;

function makeRes() {
  const res: any = { headers: {} as Record<string, string>, code: undefined as number | undefined };
  res.setHeader = (k: string, v: string) => { res.headers[k] = v; };
  res.status = (c: number) => { res.code = c; return res; };
  res.json = () => res;
  return res;
}

type U = Record<string, unknown>;
const principal = (over: U): U => ({ authMethod: 'api_key', rateLimit: 50, rateLimitWindow: 60, ...over });

/** One request through the real limiter; returns the Redis keys it incremented. */
async function call(user: U, bucket?: string): Promise<string[]> {
  const mw = enforceClientRateLimit();
  const req: any = { user };
  if (bucket) recordApiKeyBucket(req, bucket);
  const before = fakeRedis.keys.length;
  await mw(req, makeRes(), vi.fn());
  return fakeRedis.keys.slice(before);
}

let warn: ReturnType<typeof vi.spyOn>;
const noAllowanceLines = (): string[] => warn.mock.calls.map((c) => String(c[0])).filter((l) => l.includes('has no rateLimit'));
beforeAll(() => { warn = vi.spyOn(console, 'warn').mockImplementation(() => undefined); });
afterAll(() => { warn.mockRestore(); vi.restoreAllMocks(); });

describe('KS-1464 B — the jwt bucket joins its two claims injectively', () => {
  it('RED KS-1464 B1 — tenant "a:b" + id "x" and tenant "a" + id "b:x" are TWO buckets (they were both `jwt:a:b:x`)', async () => {
    CELLS_RUN += 1;
    const one = await call(principal({ tenantId: 'ks1464-a:b', connectorId: 'x1' }));
    const two = await call(principal({ tenantId: 'ks1464-a', connectorId: 'b:x1' }));
    expect(one).toHaveLength(1);
    expect(two).toHaveLength(1);
    expect(one[0], 'two different (tenant, id) pairs must not share a Redis key').not.toBe(two[0]);
  });

  it('RED KS-1464 B2 — the key stays `ratelimit:jwt:<tenant>:<id>`: four colon-separated fields even when a claim contains ":"', async () => {
    CELLS_RUN += 1;
    const [key] = await call(principal({ tenantId: 'ks1464-t:2', connectorId: 'c:2:3' }));
    expect(key.split(':'), 'a claim\'s own colons are escaped, so the key parses back to exactly its two parts').toHaveLength(4);
    expect(key.startsWith('ratelimit:jwt:')).toBe(true);
  });

  it('GREEN control KS-1464 B3 — the escape is injective over "%" as well: tenant "ks1464-p%3Aq" and tenant "ks1464-p:q" are two buckets', async () => {
    CELLS_RUN += 1;
    const lit = await call(principal({ tenantId: 'ks1464-p%3Aq', connectorId: 'x3' }));
    const col = await call(principal({ tenantId: 'ks1464-p:q', connectorId: 'x3' }));
    expect(lit[0]).not.toBe(col[0]);
  });

  it('GREEN control KS-1464 B4 — an ordinary tenant and id keep the KS-1205 key byte for byte (no rollout cost for them), and an absent tenant is still `no-tenant`', async () => {
    CELLS_RUN += 1;
    const uuid = '3caac0a0-0bf8-415b-aa31-aec9636e7ef5';
    expect(await call(principal({ tenantId: uuid, connectorId: 'conn-ks1464-4' }))).toEqual([`ratelimit:jwt:${uuid}:conn-ks1464-4`]);
    expect(await call(principal({ userId: 'u-ks1464-4' }))).toEqual(['ratelimit:jwt:no-tenant:u-ks1464-4']);
  });

  it('GREEN control KS-1464 B5 — a lone surrogate in a claim does not throw (encodeURIComponent would) and the request is still counted', async () => {
    CELLS_RUN += 1;
    const keys = await call(principal({ tenantId: 'ks1464-\uD800', connectorId: 'x5' }));
    expect(keys, 'the request was counted').toHaveLength(1);
  });

  it('GREEN control KS-1464 B6 — counting still enforces: a principal with a colon-bearing id and limit 3 gets 200,200,200 and then a 429', async () => {
    CELLS_RUN += 1;
    const user = principal({ tenantId: 'ks1464-t:6', connectorId: 'c:6', rateLimit: 3 });
    const codes: Array<number | undefined> = [];
    for (let i = 0; i < 4; i++) { const res = makeRes(); const next = vi.fn(); await enforceClientRateLimit()({ user } as any, res, next); codes.push(next.mock.calls.length === 1 ? 200 : res.code); }
    expect(codes).toEqual([200, 200, 200, 429]);
  });
});

describe('KS-1464 T — the no-allowance warning is throttled on the bucket, which carries the tenant', () => {
  it('RED KS-1464 T1 — one connectorId in two tenants logs TWO warnings (the second used to be hidden by the first)', async () => {
    CELLS_RUN += 1;
    const before = noAllowanceLines().length;
    await call(principal({ rateLimit: undefined, tenantId: 'ks1464-tenant-a', connectorId: 'ks1464-shared-t1' }));
    await call(principal({ rateLimit: undefined, tenantId: 'ks1464-tenant-b', connectorId: 'ks1464-shared-t1' }));
    expect(noAllowanceLines().length - before).toBe(2);
  });

  it('GREEN control KS-1464 T2 — the colon-ambiguous pair ("a:b"/"x" and "a"/"b:x") logs two warnings (passes on base too, because base keyed on the id alone; it pins the escaped key against a throttle key built by bare concatenation)', async () => {
    CELLS_RUN += 1;
    const before = noAllowanceLines().length;
    await call(principal({ rateLimit: undefined, tenantId: 'ks1464-t2:b', connectorId: 'x2' }));
    await call(principal({ rateLimit: undefined, tenantId: 'ks1464-t2', connectorId: 'b:x2' }));
    expect(noAllowanceLines().length - before).toBe(2);
  });

  it('RED KS-1464 T3 — the warning names the tenant, so two tenants\' lines are not the same line', async () => {
    CELLS_RUN += 1;
    const before = noAllowanceLines().length;
    await call(principal({ rateLimit: undefined, tenantId: 'ks1464-tenant-named', connectorId: 'ks1464-t3' }));
    const line = noAllowanceLines().slice(before)[0];
    expect(line).toContain('ks1464-t3');
    expect(line, 'the tenant is in the line').toContain('ks1464-tenant-named');
  });

  it('RED KS-1464 T4 — two API keys of one connector (two recorded buckets) each get their own warning slot: the throttle follows the bucket', async () => {
    CELLS_RUN += 1;
    const before = noAllowanceLines().length;
    const user = principal({ rateLimit: undefined, tenantId: 'ks1464-tenant-t4', connectorId: 'ks1464-t4' });
    await call({ ...user }, 'api_key:' + 'a'.repeat(64));
    await call({ ...user }, 'api_key:' + 'b'.repeat(64));
    expect(noAllowanceLines().length - before).toBe(2);
  });

  it('GREEN control KS-1464 T5 — one principal, 25 requests, ONE warning; and the same recorded bucket twice is ONE warning', async () => {
    CELLS_RUN += 1;
    const before = noAllowanceLines().length;
    for (let i = 0; i < 25; i++) await call(principal({ rateLimit: undefined, tenantId: 'ks1464-tenant-t5', connectorId: 'ks1464-t5' }));
    expect(noAllowanceLines().length - before, 'a repeated principal is throttled').toBe(1);
    const u = principal({ rateLimit: undefined, tenantId: 'ks1464-tenant-t5b', connectorId: 'ks1464-t5b' });
    await call({ ...u }, 'api_key:' + 'c'.repeat(64));
    await call({ ...u }, 'api_key:' + 'c'.repeat(64));
    expect(noAllowanceLines().length - before).toBe(2);
  });
});

describe('KS-1464 completeness', () => {
  it('KS-1464 COMPLETENESS — every graded cell above actually ran', () => {
    expect(CELLS_RUN).toBe(EXPECTED_CELLS);
  });
});
